    if (s.marker === 'square') return `<rect x="${p.x-5}" y="${p.y-5}" width="10" height="10" fill="#fffdf9" stroke="${s.color}" stroke-width="3"/>`;
    if (s.marker === 'diamond') return `<path d="M ${p.x} ${p.y-7} L ${p.x+7} ${p.y} L ${p.x} ${p.y+7} L ${p.x-7} ${p.y} Z" fill="#fffdf9" stroke="${s.color}" stroke-width="2.8"/>`;
    return `<path d="M ${p.x} ${p.y-7} L ${p.x+7} ${p.y+6} L ${p.x-7} ${p.y+6} Z" fill="#fffdf9" stroke="${s.color}" stroke-width="2.8"/>`;
  }).join('\n');
}
function calloutFor(s) {
  const p = pointFor(s, s.calloutYear);
  const tx = p.x + s.calloutDx;
  const ty = p.y + s.calloutDy;
  const lines = s.callout.split('\n');
  const text = lines.map((line, i) => `<tspan x="${tx}" dy="${i ? 22 : 0}">${esc(line)}</tspan>`).join('');
  return `<g class="callout">
    <path d="M ${tx + (s.calloutDx > 0 ? -10 : 180)} ${ty + 18} Q ${(tx+p.x)/2} ${(ty+p.y)/2} ${p.x} ${p.y}" fill="none" stroke="${s.color}" stroke-width="2.2" stroke-dasharray="5 5" opacity="0.9"/>
    <circle cx="${p.x}" cy="${p.y}" r="8" fill="${s.color}" stroke="#fffdf9" stroke-width="3"/>
    <text class="callout-text" fill="${s.color}" x="${tx}" y="${ty}">${text}</text>
  </g>`;
}
function legend() {
  const startX = margin.left + 5;
  const y0 = 995;
  return `<g class="legend">
    ${series.map((s, i) => {
      const cx = startX + i * 375;
      const lineDash = s.dash ? `stroke-dasharray="${s.dash}"` : '';
      return `<g transform="translate(${cx}, ${y0})">
        <line x1="0" x2="58" y1="0" y2="0" stroke="${s.color}" stroke-width="5" ${lineDash}/>
        <text class="legend-label" x="70" y="-7">${esc(s.short)}</text>
        <text class="legend-unit" x="70" y="17">${esc(s.unit)} · ${esc(s.note)}</text>
      </g>`;
    }).join('\n')}
  </g>`;
}

